# Mutations judged equivalent (no observable difference) or beyond what the
# simulated client can show; kept here so they aren't re-proposed.
EQUIVALENT = {
    'answer order (list before turned-in list)': "not in the list: swapping SendDone/SendList in AnswerListRequest only matters while the channel is throttled, for the moment between the two messages",
    'r29: turned-in list waits on a same-session request': "since pickups are answered (a quest they picked up while we were away arrives in their list and is answered at once), the request path only sends the same list a moment sooner",
    'r28: held forced turned-in list downgraded': 'beyond the tests: needs a third DuoQuest player whose list is still on its way plus an unforced send in the same 20s, and the next heartbeat (a minute) repairs it',
    'r28: old hello time after their reload': 'beyond the tests: only a partner who never synced for over 20s and then reloads; a turned-in list built from nothing goes out a moment before their list arrives and the real one replaces it',
    'r27: every gap counted as ignored': 'the count is only read when no gap is left to list, and then every one counted is an ignored one',
    'r22: bar need not 100': "a progress bar's need is never shown (the percent and the done flag are)",
    'push without index': 'the quest is selected first, so a push with or without its index shares it',
    'r14: held rest info': 'a hold needs you to have left the inn already (its door is marked), and walking back in rests again',
    'r14: mineReady in CheckLeaving': 'the channel is off until the log is read, so there is no partner data before it',
    'r13: door window marks while flying': 'the window never opens on a taxi, and takeoff starts a new hub, which closes it',
    'r4: inn door is leaving (immediate mark)': "the tick's door window marks the same area within half a second",
    'r8: (fix probe) Apart unguarded': 'Apart does not throw; the pcall is a guard',
    'r9: lastNeedList limit': 'in a duo the per-partner NEED_GAP already spaces these',
    'r7: secret map read as missing': 'rawequal never throws, and a secret is never raw nil',
    'r7: (fix probe) apart result': 'Apart does not throw; the pcall is a guard',
    'r7: last heard not saved': 'the heartbeat list refreshes it at least every minute, inside the 2-minute window',
    'r8: syncOff not cleared on a new session': 'syncOff is only read when there is no partner record, and the session event creates one',
    'r8: resync never cleared': 'synced is checked first wherever both are read (the status line\'s Resyncing/Syncing wording only differs before a list arrives); a stale partner\'s note only waits longer before giving up',
    'r8: list prune of pickup times': 'only matters for a re-pickup whose removal message was lost (the stale time is then kept): no practical effect',
    'r8: KEEP_PARTNERS': 'saved-file size only',
    'r4: told never forgotten': 'a re-pickup clears its entry anyway; the prune only keeps the saved list short',
    'r6: loadedAt on hearth success': 'Arrived() at the same moment leaves nothing fresh for a later "You left"',
    'r6: WalkBackFirst title tie-break': 'order of equal-priority names only',
    'r5: secret IsOnQuest read as gone': 'nil (can\'t tell) and false (gone) both drop the quest from the scan',
    'r5: reload subject to relog rule': 'differs only for a /reload after 10+ minutes dead or flying, or with an unreadable zone name',
    'r5: Gaps age > since': 'same-second edge',
    'r5: hello not at front': 'Hello(true) runs with an empty queue; the other hellos only get later, never lost',
    'r5: hello instead of list after a loading screen': 'converges either way; costs a full exchange',
    'r3: protocol length unchecked': 'a long protocol number is out of range anyway',
    'r3: request without done list': 'superseded: the request now sends the turned-in list when we hold their list (see r28/r29 entries)',
    'notes from stale data': "a stale partner sends nothing: his pickup and finish notes need his messages, and yours waits for his answer",
    'reply even right after own hello': 'the per-peer request limit already stops repeat answers',
    'r3: ADDON_LOADED for other addons': "re-running setup on another addon's ADDON_LOADED is harmless",
    'r3: IsDone pcall fail': 'the API never throws in practice',
    'r3: no scan debounce': 'efficiency only',
    'r3: seenAt never pruned': 'saved-file growth only',
    'r3: seenAt kept after list drop': 'a re-added quest normally gets a new pickup time; only a lost removal message keeps the old one',
    'r3: N counts as data': 'only shifts the quiet-period timing of resend requests',
    "r3: request doesn't refresh heard": 'partners always send data, which refreshes it',
    "r3: sync on doesn't resend done": "code removed (the hello's request forces the done list)",
    'r3: no deferred hello': 'joining calls Hello from the roster update',
    'r3: no hello when all stale': 'code removed (the heartbeat list makes the partner say hello)',
    'r3: N to stale partner': 'efficiency only',
    'r3: N to departed partner': 'efficiency only',
    'r3: title tie order': 'only with duplicate titles',
    'r3: warn without info': 'code removed (dead)',
    'r3: pending dup': 'code removed (told prevents duplicates)',
    'r3: notes queued while off': 'code removed (the tick drops them)',
    'r3: commands before load': 'unreachable',
    'r3: Done without identity check': 'defensive',
    'r3: skipped entry keeps again': 'defensive',
    'r3: assembled parts kept': 'memory only',
    'r3: partners prune via Sync loop removed': 'code removed',
    'r3: login told reset (dead?)': 'code removed',
    'r3: held forever': 'behavior changed: held warnings now always wait for the fight',
}


def run_tests(copy):
    env = dict(os.environ, DQ_DIR=copy + "/", DQ_TESTS=HERE + "/")
    suites = sorted(f for f in os.listdir(HERE) if f.startswith("tests") and f.endswith(".lua"))
    for suite in suites:
        try:
            r = subprocess.run(["lua5.1", os.path.join(HERE, suite)], env=env, capture_output=True, text=True, timeout=600)
        except subprocess.TimeoutExpired:
            return False  # (a mutant that hangs the suite is caught)
        if r.returncode != 0:
            return False
    return True


def try_one(args):
    index, (file, old, new, label) = args
    base = tempfile.mkdtemp(prefix="dq-mut-")
    try:
        copy = os.path.join(base, "addon")
        shutil.copytree(ADDON, copy, ignore=shutil.ignore_patterns("tests"))
        path = os.path.join(copy, file)
        src = open(path).read()
        if src.count(old) != 1:
            return label, "skip", src.count(old)
        open(path, "w").write(src.replace(old, new, 1))
        return label, ("survived" if run_tests(copy) else "caught"), 1
    finally:
        shutil.rmtree(base)


def check_patterns():
    """Fast check (run.sh runs it): every pattern still matches its file exactly
    once, labels are unique, and no EQUIVALENT label is still in the list."""
    bad = []
    labels = [m[3] for m in MUTATIONS]
    for label in set(labels):
        if labels.count(label) > 1:
            bad.append(f"duplicate label: {label}")
    for file, old, new, label in MUTATIONS:
        n = open(os.path.join(ADDON, file)).read().count(old)
        if n != 1:
            bad.append(f"pattern found {n} times: {label}")
        if old == new:
            bad.append(f"no change: {label}")
        if label in EQUIVALENT:
            bad.append(f"both listed and EQUIVALENT: {label}")
        if n == 1 and file.endswith(".lua"):
            # (a mutant that doesn't even compile is "caught" by the load error, testing nothing)
            src = open(os.path.join(ADDON, file)).read().replace(old, new, 1)
            r = subprocess.run(["luac5.1", "-p", "-"], input=src, capture_output=True, text=True)
            if r.returncode != 0:
                bad.append(f"mutant doesn't compile: {label}: {r.stderr.strip()}")
    for line in bad:
        print(line)
    print(f"mutate.py: {len(MUTATIONS)} patterns, {len(bad)} problems")
    return not bad


def main():
    if "--check" in sys.argv:
        sys.exit(0 if check_patterns() else 1)
    # DQ_ONLY=<prefix>: only mutations whose label starts with it.
    only = os.environ.get("DQ_ONLY", "")
    todo = [m for m in MUTATIONS if m[3].startswith(only)]
    from concurrent.futures import ProcessPoolExecutor
    survived, applied, skipped = [], 0, 0
    with ProcessPoolExecutor(max_workers=os.cpu_count() or 2) as pool:
        for label, result, count in pool.map(try_one, enumerate(todo)):
            if result == "skip":
                skipped += 1
                print(f"SKIP (pattern found {count} times): {label}")
                continue
            applied += 1
            if result == "survived":
                survived.append(label)
                print(f"SURVIVED: {label}", flush=True)
    print(f"{applied - len(survived)}/{applied} mutations caught")
    sys.exit(1 if survived or skipped else 0)


if __name__ == "__main__":
    main()
